import{_ as a,c as r,o,b0 as i}from"./chunks/framework.Dmsv_Tiv.js";const d="/media-docs/assets/image-20251225161017794.Cm4QdHmf.png",s="/media-docs/assets/image-20251225161034575.CH0juQga.png",l="/media-docs/assets/image-20251225161054167.HALRhl3P.png",n="/media-docs/assets/image-20251226092237453.62VMPL7v.png",c="/media-docs/assets/image-20251226093700494.C0kCppqj.png",p="/media-docs/assets/image-20251226103825940.D2_zlVsa.png",h="/media-docs/assets/image-20251226103832044.I0Rpb36-.png",m="/media-docs/assets/image-20251226103837474.Co70WOyt.png",g="/media-docs/assets/image-20251226112637930.BVlyd6Uh.png",e="/media-docs/assets/image-20251226093833383.DgSOpP1y.png",b="/media-docs/assets/image-20251226103747035.CtydcIx5.png",_="/media-docs/assets/image-20251226103751842.DY4n-LFQ.png",u="/media-docs/assets/image-20251226103606941.D8CJtsfI.png",y="/media-docs/assets/image-20251226103613094.95phH2A5.png",C="/media-docs/assets/image-20251226104405700.Ds8QdDy4.png",A="/media-docs/assets/image-20251226104443013.DZrj_pwm.png",q="/media-docs/assets/image-20251226104449277.CkiDWnc6.png",f="/media-docs/assets/1003156-20200808214400056-99332476.Cq_bRRYO.jpg",k="/media-docs/assets/image-20251226104927778.C2_3wYk2.png",P="/media-docs/assets/image-20251226104933070.CnjGKSdX.png",v=JSON.parse('{"title":"LV005-概述","description":null,"frontmatter":{"title":"LV005-概述","date":"2025-12-24T14:53:39.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/acodec/audio-alg/126b1b057dbb23b0d4b42009","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-12-24T14:53:39.571Z","fulluuid":"0d4b420096d34575a9a5dd114778737c","useduuid":"0d4b42009"}},"headers":[],"relativePath":"sdoc/acodec/audio-alg/126b1b057dbb23b0d4b42009.md","filePath":"sdoc/25-音频编解码/40-音频算法/LV005-概述.md","lastUpdated":1767537778000}'),S={name:"sdoc/acodec/audio-alg/126b1b057dbb23b0d4b42009.md"};function x(L,t,w,N,D,G){return o(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="lv005-概述" tabindex="-1">LV005-概述 <a class="header-anchor" href="#lv005-概述" aria-label="Permalink to &quot;LV005-概述&quot;">​</a></h1><h2 id="一、音频数据流" tabindex="-1">一、音频数据流 <a class="header-anchor" href="#一、音频数据流" aria-label="Permalink to &quot;一、音频数据流&quot;">​</a></h2><p>一般来说，会遇到以下数据流的情况：</p><ul><li>录音</li></ul><p><img src="'+d+'" alt="image-20251225161017794"></p><ul><li>对讲</li></ul><p><img src="'+s+'" alt="image-20251225161034575"></p><ul><li>录音</li></ul><p><img src="'+l+'" alt="image-20251225161054167"></p><p>也并不都是按照上面的数据流，主要看需求，需要加哪些算法。</p><h2 id="二、常用音频算法" tabindex="-1">二、常用音频算法 <a class="header-anchor" href="#二、常用音频算法" aria-label="Permalink to &quot;二、常用音频算法&quot;">​</a></h2><table><tbody><tr><td> AEC(Acoustic echo cancellation)</td><td> 回声消除 </td><td> 消除回声，尤其是在通话或会议过程中，扬声器声音被麦克风拾取，导致反复回传形成回声。</td></tr><tr><td> AGC(Automatic Gain Control)</td><td> 自动增益控制 </td><td> 自动调节音量，使得音频信号的强度保持在一个稳定的范围内，防止声音过大或过小。</td></tr><tr><td> ALC(Automatic Level Control)</td><td> 线性增益控制 </td><td> ALC 常用来稳定输出功率幅度，个人理解就是一个线性放大的算法，对音频整体进行放大。</td></tr><tr><td> NR(Noise Suppression)</td><td> 降噪 </td><td> 抑制背景噪声，如风声、键盘声、交通噪声等，以提高语音的清晰度和质量。</td></tr><tr><td> ANC(Active Noise Control)</td><td> 主动噪声控制 </td><td> 感觉和 NR 一样，只是不同的叫法。</td></tr><tr><td> HS(howling suppression)</td><td> 啸叫抑制算法 </td><td> 啸叫噪声往往比较尖锐刺耳，通过 HS 算法进行抑制。</td></tr></tbody></table><h3 id="_1-声学回声消除-aec" tabindex="-1">1. 声学回声消除 AEC <a class="header-anchor" href="#_1-声学回声消除-aec" aria-label="Permalink to &quot;1. 声学回声消除 AEC&quot;">​</a></h3><h4 id="_1-1-简介" tabindex="-1">1.1 简介 <a class="header-anchor" href="#_1-1-简介" aria-label="Permalink to &quot;1.1 简介&quot;">​</a></h4><p>在语音通信中，扬声器播放出的声音由终端麦克风采集到传输给远端，使远端说话者听到自己的声音，形成声学回声。声学回声严重影响着通话的语音质量，如何更好地消除声学回声一直是算法工程师关注的焦点。由于产生声学回声的系统是时变非线性系统，所以通常的声学回声消除算法包括自适应滤波器和非线性处理两个模块：自适应滤波器负责模拟和跟踪回声路径，消除一部分线性回声；非线性处理则进一步对残留的回声进行抑制， 如下图所示：</p><img src="'+n+'" alt="image-20251226092237453" style="zoom:67%;"><p>常见的自适应滤波算法有最小均方算法（LMS, Least Mean Square），归一化最小均方算法（NLMS, Normalized Least Mean Square），仿射投影算法（APA, Affine Projection Algorithm），递归最小二乘法（RLS， Recursive Least Squares），以及这些算法的衍生算法。 AEC 模块在系统中的位置一般如下所示：</p><p><img src="'+c+'" alt="image-20251226093700494"></p><h4 id="_1-2-效果展示" tabindex="-1">1.2 效果展示 <a class="header-anchor" href="#_1-2-效果展示" aria-label="Permalink to &quot;1.2 效果展示&quot;">​</a></h4><p>经过 AEC 的处理可以消除回采到的扬声器播放的声音，l 效果与陈列回声消除效果接近。AEC 效果示意如下：</p><table><tbody><tr style="border:none;"><td align="center" style="border:none;"> Ref </td><td align="center" style="border:none;"><img src="'+p+'" style="width:100%;height:auto;" alt="img"></td></tr><tr style="border:none;"><td align="center" style="border:none;"> Input </td><td align="center" style="border:none;"><img src="'+h+'" style="width:100%;height:auto;" alt="img"></td></tr><tr style="border:none;"><td align="center" style="border:none;"> Output </td><td align="center" style="border:none;"><img src="'+m+'" style="width:100%;height:auto;" alt="img"></td></tr></tbody></table> #### 1.4 基本原理 <p>估计回声路径的特征参数，产生一个模拟的回声通络，得到估计的回声信号，从接收信号中减去该信号，实现回声消除。可能存在的问题有：双讲抑制</p><p>和回声残留。</p><p><img src="'+g+'" alt="image-20251226112637930"></p><h3 id="_2-自动增益-agc" tabindex="-1">2. 自动增益 AGC <a class="header-anchor" href="#_2-自动增益-agc" aria-label="Permalink to &quot;2. 自动增益 AGC&quot;">​</a></h3><h4 id="_2-1-简介" tabindex="-1">2.1 简介 <a class="header-anchor" href="#_2-1-简介" aria-label="Permalink to &quot;2.1 简介&quot;">​</a></h4><p>在音视频通话的现实场景中，由于不同人的说话音量不同，同一人可能在不同地方说话，麦克风增益的不同等原因，导致麦克风端收到的信号大小不一，远端的人也会听到时大时小的音量，甚至扬声器破音与音量过小的情况均会发生。因此，对发送端音量的均衡是很有必要的。</p><p>自动增益控制（AGC, Auto Gain Control）可以极大地缓解有设备差异、说话人音量大小、距离远近灯因素导致的音量的差异，提升对端听着的主观听感。 AGC 算法通常位于音频前端算法上行处理和下行处理的最后一个模块，如图 ：</p><p><img src="'+e+'" alt="image-20251226093833383"></p><h4 id="_2-2-效果展示" tabindex="-1">2.2 效果展示 <a class="header-anchor" href="#_2-2-效果展示" aria-label="Permalink to &quot;2.2 效果展示&quot;">​</a></h4><p>主要效果就是提高远距离或小声说话的声音，压制近距离或大声说话的声音。AGC 效果如下：</p><table><tbody><tr style="border:none;"><td align="center" style="border:none;"> 原始信号 </td><td align="center" style="border:none;"><img src="'+b+'" style="width:100%;height:auto;" alt="img"></td></tr><tr style="border:none;"><td align="center" style="border:none;"> 使用 agc 后 </td><td align="center" style="border:none;"><img src="'+_+'" style="width:100%;height:auto;" alt="img"></td></tr></tbody></table> #### 2.3 基本原理 <p>首先判断噪声段和语音段，然后将语音段赋值拉升或压缩至目标增益范围。可能出现的问题如下：</p><ul><li><p>AGC 处理需要收敛时间，远近音源切换是会有一个渐变过程。</p></li><li><p>如果远近音源同时发声时，远处音源拉升较小。</p></li><li><p>开启压制功能后，语音会有所抑制，通常关闭 AGC 的压制功能。</p></li></ul><h3 id="_3-线性增益控制-alc" tabindex="-1">3. 线性增益控制 ALC <a class="header-anchor" href="#_3-线性增益控制-alc" aria-label="Permalink to &quot;3. 线性增益控制 ALC&quot;">​</a></h3><h4 id="_3-1-简介" tabindex="-1">3.1 简介 <a class="header-anchor" href="#_3-1-简介" aria-label="Permalink to &quot;3.1 简介&quot;">​</a></h4><p>由于 AGC 的特性， 当目标增益足够大时， 对极小的信号将会得到更大的放大，使得对端听到被放大的底噪。为了让小信号放大倍数得到控制的同时语音信号得到应有的放大倍数，可以减小 AGC 的目标增益，同时对信号进行线性放大（ALC）。</p><p><img src="'+e+'" alt="image-20251226093833383"></p><p>感觉网上资料不多，没有很多会提到音频中的 alc 算法，有一些多媒体处理平台会带，个人理解就是一个调整整体信号增益的算法，比如统一放大多少倍这种。</p><h4 id="_3-2-效果展示" tabindex="-1">3.2 效果展示 <a class="header-anchor" href="#_3-2-效果展示" aria-label="Permalink to &quot;3.2 效果展示&quot;">​</a></h4><p>这里有一个 alc 算法使用前后的效果图：</p><table><tbody><tr style="border:none;"><td align="center" style="border:none;"> 原始信号 </td><td align="center" style="border:none;"><img src="'+u+'" style="width:100%;height:auto;" alt="img"></td></tr><tr style="border:none;"><td align="center" style="border:none;"> 使用 alc 后 </td><td align="center" style="border:none;"><img src="'+y+'" style="width:100%;height:auto;" alt="img"></td></tr></tbody></table> ### 4. 环境噪声抑制 ANC <h4 id="_4-1-简介" tabindex="-1">4.1 简介 <a class="header-anchor" href="#_4-1-简介" aria-label="Permalink to &quot;4.1 简介&quot;">​</a></h4><p>在语音通信中， 麦克风不可避免的会采集到环境底噪，底噪经过增益放大后，使对端听到夹杂着噪声的语音，影响着通话质量。为了提升通话语音质量，对麦克风信号的降噪环节必不可少。 降噪模块在整个音频算法中的位置如图 ：</p><p><img src="'+C+'" alt="image-20251226104405700"></p><h4 id="_4-2-效果展示" tabindex="-1">4.2 效果展示 <a class="header-anchor" href="#_4-2-效果展示" aria-label="Permalink to &quot;4.2 效果展示&quot;">​</a></h4><p>可以降低环境中的平稳噪声（空调、风扇等），但降噪效果远不如陈列降噪算法，并且对语音损伤更大。ANC 效果如下：</p><table><tbody><tr style="border:none;"><td align="center" style="border:none;"> 原始信号 </td><td align="center" style="border:none;"><img src="'+A+'" style="width:100%;height:auto;" alt="img"></td></tr><tr style="border:none;"><td align="center" style="border:none;"> 使用 ANC 后 </td><td align="center" style="border:none;"><img src="'+q+'" style="width:100%;height:auto;" alt="img"></td></tr></tbody></table> #### 4.3 基本原理 <p>噪声与语音信号特性不同，实时估计噪声信号，然后利用估计的噪声信号去降低原始数据中的噪声。可能存在的问题：</p><ul><li><p>不能彻底区分语音和噪声，会对语音产生一定的损伤</p></li><li><p>非平稳噪声无法处理（键盘声、走路声）</p></li><li><p>降噪能力相对较弱</p></li></ul><h3 id="_5-啸叫抑制-hs" tabindex="-1">5. 啸叫抑制 HS <a class="header-anchor" href="#_5-啸叫抑制-hs" aria-label="Permalink to &quot;5. 啸叫抑制 HS&quot;">​</a></h3><h4 id="_5-1-简介" tabindex="-1">5.1 简介 <a class="header-anchor" href="#_5-1-简介" aria-label="Permalink to &quot;5.1 简介&quot;">​</a></h4><p>当一个人在演讲或演唱时，他们的声音会被话筒捕捉，随后通过扩音系统在音箱中放大并播放出来。这个过程会形成一个循环：音箱中放大的声音再次被同一话筒拾取，然后再次通过扩音系统放大，接着再次被拾取。这个声音信号的连续循环和放大过程，我们称之为“回授”，也就是声反馈现象。如果这个循环的增益足够大，就会导致声音信号的不断增强，最终产生尖锐的啸叫声，即我们通常所说的啸叫，啸叫抑制也叫声反馈抑制。</p><p><img src="'+f+'" alt="img"></p><p>对于啸叫的音频，音色会比较尖锐。如果从频谱上看，则可看到少数频点的能量相较于整个频带尤其突出，且多数分布在中高频。这些能量较大的频点就是啸叫频点，需要对这些频点进行抑制。</p><h4 id="_5-2-效果展示" tabindex="-1">5.2 效果展示 <a class="header-anchor" href="#_5-2-效果展示" aria-label="Permalink to &quot;5.2 效果展示&quot;">​</a></h4><p>HS 效果如下：</p><table><tbody><tr style="border:none;"><td align="center" style="border:none;"> 原始信号 </td><td align="center" style="border:none;"><img src="'+k+'" style="width:100%;height:auto;" alt="img"></td></tr><tr style="border:none;"><td align="center" style="border:none;"> 使用 HS 后 </td><td align="center" style="border:none;"><img src="'+P+'" style="width:100%;height:auto;" alt="img"></td></tr></tbody></table><blockquote><p>参考资料：</p><p><a href="https://blog.csdn.net/qq_28258885/article/details/120175673" target="_blank" rel="noreferrer">音频处理——常用音频算法名词简称解释(AEC、AGC、NS、HPF、BSS、BF、DOA、DER)-CSDN 博客</a></p><p><a href="https://www.cnblogs.com/LXP-Never/p/11693567.html" target="_blank" rel="noreferrer">主动噪声控制 (Active Noise Control, ANC)理论及 Matlab 代码实现 - 凌逆战 - 博客园</a></p><p><a href="https://blog.csdn.net/helaisun/article/details/105917259" target="_blank" rel="noreferrer">声学回声消除(Acoustic Echo Cancellation)原理与实现-CSDN 博客</a></p><p><a href="https://zhuanlan.zhihu.com/p/360658602" target="_blank" rel="noreferrer">(7 封私信) AGC/ALC 自动增益/电平控制 - 知乎</a></p></blockquote>',63)])])}const E=a(S,[["render",x]]);export{v as __pageData,E as default};
